  Eje = `Zresetuj aktywację`,
  Dje = `Dodaj polecenie`,
  Oje = `Usuń to polecenie`,
  kje = `Usuń`,
  Aje = `Aktywacja`,
  jje = `Ustawienia`,
  Mje = `Wyczyść z nadrzędnego zestawu działań`,
  Nje = `Zresetuj na dziedziczony`,
  Pje = `Zmień nazwę polecenia`,
  Fje = `Zmień nazwę grupy poleceń`,
  Ije = `Usuń wszystkie polecenia`,
  Lje = `Edytuj synchronizację wielu przypisań`,
  Rje = `Dostosuj czas`,
  zje = `Przypisania wielokrotne można wizualizować i dostosowywać na ekranie dedykowanego edytora.`,
  Bje = `Rozwiń`,
  Vje = `Zwiń`,
  Hje = `%1$s (%2$s)`,
  Uje = `Synchronizacja wielu przypisań`,
  Wje = `Każdy pasek to jedno polecenie tworzone przez ten element sterowania w ciągu jednego wciśnięcia. Czas jest w milisekundach. Przenieś uchwyty początku i końca danego paska, by zmienić moment aktywacji i dezaktywacji polecenia.`,
  Gje = `Oś czasu`,
  Kje = `Polecenia`,
  qje = `Wciśnięcie`,
  Jje = `Zwolnienie`,
  Yje = `Długość symulowanego wciśnięcia przycisku`,
  Xje = `Jak długo przycisk jest trzymany w tym podglądzie. Polecenia odpowiadające na zwolnienie są przesuwane wraz z nim.`,
  Zje = `%1$s ms`,
  Qje = `+%1$s ms`,
  $je = `Aktywuj`,
  eMe = `Dezaktywuj`,
  tMe = `Start`,
  nMe = `Zakończ`,
  rMe = `%1$s%`,
  iMe = `Wciśnięcie musi trwać przynajmniej %1$s, by to polecenie zostało aktywowane.`,
  aMe = `%1$s jest aktywowane wraz z tym wciśnięciem, a to polecenie jest określone jako możliwe do przerwania, więc jest pomijane.`,
  oMe = `Ten element sterowania tworzy tylko jedno polecenie, więc nie ma żadnej synchronizacji do ustawienia. Jej opóźnienia są podane poniżej.`,
  sMe = `Zmień kolejność działań według czasu rozpoczęcia`,
  cMe = `Sortuj`,
  lMe = `Przypisanie wielokrotne bez nazwy`,
  uMe = `Nieprzypisane`,
  dMe = `Mysz`,
  fMe = `W użyciu`,
  pMe = `%1$s (%2$s)`,
  mMe = `Analogowe`,
  hMe = `Spust`,
  gMe = `Przycisk`,
  _Me = `Dodaj element sterowania`,
  vMe = `Zmień element sterowania`,
  yMe = `Zmień polecenie`,
  bMe = `Usuń element sterowania`,
  xMe = `Edytuj element sterowania`,
  SMe = `Ustawienia`,
  CMe = `Wybierz element sterowania dla: %1$s`,
  wMe = `Wybierz tryb dla %1$s`,
  TMe = `Odbija wirtualny drążek, bezpośrednio używając pozycji na panelu dotykowym, by kontrolować, jak daleko ma być odbity.`,
  EMe = `Odbija wirtualny drążek, bezpośrednio używając pozycji żyroskopu, by kontrolować, jak daleko ma być odbity.`,
  DMe = `Przesuwa kursor myszy ze stałą prędkością, dopóki przytrzymujesz odbicie – tym szybciej, im dalej pchasz.`,
  OMe = `Przesuwa kursor myszy w kierunku, w którym poruszasz się po padzie, tak jak po panelu dotykowym laptopa.`,
  kMe = `Starszy tryb drążka jako myszy zachowany dla konfiguracji, które już go używają.`,
  AMe = `Zamienia ruch kontrolera na ruch myszy – celujesz, pochylając go.`,
  jMe = `Wysyła dane drążka kontrolującego kamerę. Dystans wychylenia ustala szybkość obrotu kamery.`,
  MMe = `Zamienia ruch kontrolera na ruch drążka kontrolujący kamerę. Używane dla gier, które odczytują drążek zamiast myszy.`,
  NMe = `Zmienia ruch kontrolera na odbicie drążka, tak jakbyś wychylał drążek o taki dystans.`,
  PMe = `Mapuje panel dotykowy do regionu na ekranie, więc miejsce na panelu zawsze wskazuje na to samo miejsce.`,
  FMe = `Wysyła kąt kamery bezpośrednio do gry. Używane dla gier, które to obsługują, zamiast ruchu myszy czy drążka kreowanego przez inne tryby.`,
  IMe = `Pozostawia element sterowania bezczynnym, gdy ta opcja jest wybrana.`,
