  IHe = `Polecenie pada kierunkowego w górę`,
  LHe = `To polecenie zostanie wykonane po wciśnięciu „w górę” na padzie kierunkowym.`,
  RHe = `Polecenie pada kierunkowego w dół`,
  zHe = `To polecenie zostanie wykonane po wciśnięciu „w dół” na padzie kierunkowym.`,
  BHe = `Przytrzymaj, by powtórzyć (Turbo)`,
  VHe = `Gdy ta opcja jest włączona, przytrzymanie kierunku spowoduje jego powtarzanie (tak zwany „tryb turbo”).`,
  HHe = `Przytrzymaj, by powtórzyć (Turbo) – wł.`,
  UHe = `Gdy ta opcja jest włączona, przytrzymanie kierunku spowoduje jego powtarzanie (tak zwany „tryb turbo”).`,
  WHe = `Przytrzymaj, by powtórzyć (Turbo) – wył.`,
  GHe = `Gdy ta opcja jest włączona, przytrzymanie kierunku spowoduje jego powtarzanie (tak zwany „tryb turbo”).`,
  KHe = `Okres powtarzania`,
  qHe = `Gdy tryb turbo jest włączony, ta opcja reguluje częstotliwość powtarzania. Przesuń w prawo dla częstszego powtarzania.`,
