  Dnt = `Odwróć oś poziomą`,
  Ont = `Włączenie spowoduje, że ruch na panelu w lewo poruszy myszą w prawo, a ruch na panelu w prawo poruszy myszą w lewo. Weź pod uwagę, że niektóre ustawienia gry mają tę opcję, więc upewnij się, że nie wykluczają się nawzajem.`,
  knt = `Odwróć oś poziomą – wł.`,
  Ant = `Włączenie spowoduje, że ruch na panelu w lewo poruszy myszą w prawo, a ruch na panelu w prawo poruszy myszą w lewo. Weź pod uwagę, że niektóre ustawienia gry mają tę opcję, więc upewnij się, że nie wykluczają się nawzajem.`,
  jnt = `Odwróć oś poziomą – wył.`,
  Mnt = `Pozioma oś myszki będzie funkcjonować normalnie, a ruch w lewo na płytce będzie odpowiadał ruchowi w lewo na myszce.`,
  Nnt = `Odwróć oś pionową`,
  Pnt = `Włączenie spowoduje, że ruch na panelu w górę poruszy myszą w dół, a ruch na panelu w dół poruszy myszą w górę. Weź pod uwagę, że niektóre ustawienia gry mają tę opcję, więc upewnij się, że nie wykluczają się nawzajem.`,
  Fnt = `Odwróć oś pionową – wł.`,
  Int = `Włączenie spowoduje, że ruch na panelu w górę poruszy myszą w dół, a ruch na panelu w dół poruszy myszą w górę. Weź pod uwagę, że niektóre ustawienia gry mają tę opcję, więc upewnij się, że nie wykluczają się nawzajem.`,
  Lnt = `Odwróć oś pionową – wył.`,
